function validate(input) {
  const [{ Candidate = [], Vote = [] }] = input;
  const candidates = new Set(), ballots = new Set(), counts = new Map();
  for (const [id] of Candidate) {
    if (id === null) return 'Every candidate needs an id.';
    if (candidates.has(id)) return `Candidate id ${id} appears twice.`;
    candidates.add(id);
  }
  for (const [id, candidateId] of Vote) {
    if (id === null) return 'Every vote needs an id.';
    if (ballots.has(id)) return `Vote id ${id} appears twice.`;
    if (!candidates.has(candidateId)) return `Vote ${id} names candidate ${candidateId}, who is not in Candidate.`;
    ballots.add(id);
    counts.set(candidateId, (counts.get(candidateId) ?? 0) + 1);
  }
  if (Vote.length === 0) return 'There must be at least one vote.';
  const top = Math.max(...counts.values());
  if ([...counts.values()].filter(c => c === top).length > 1) return 'Two candidates tie for the most votes.';
  return null;
}

generator:
function generate(rand, size) {
  const names = ['A', 'B', 'C', 'Ana', 'Bob', 'Lee', 'Kim', 'Ravi'];
  const small = size === 'small';
  const people = small ? 1 + Math.floor(rand() * 6) : 300;
  const ballots = small ? 1 + Math.floor(rand() * 7) : 1999;
  const Candidate = [], Vote = [];
  // Ids are spaced so that a ballot id rarely equals the candidate it names.
  for (let i = 1; i <= people; i++) Candidate.push([i * 3, names[Math.floor(rand() * names.length)]]);
  const counts = new Map();
  for (let i = 1; i <= ballots; i++) {
    // Skew the choice so that a few candidates collect most of the votes.
    const pick = Candidate[Math.floor(rand() * rand() * people)][0];
    Vote.push([i, pick]);
    counts.set(pick, (counts.get(pick) ?? 0) + 1);
  }
  // Break a tie at the top with one extra ballot so the winner is unique.
  const top = Math.max(...counts.values());
  const leaders = [...counts.keys()].filter(id => counts.get(id) === top);
  if (leaders.length > 1) Vote.push([ballots + 1, leaders[Math.floor(rand() * leaders.length)]]);
  // Shuffle ballot order so the winner's votes are spread through the table.
  for (let i = Vote.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [Vote[i][1], Vote[j][1]] = [Vote[j][1], Vote[i][1]]; }
  return [{ Candidate, Vote }];
}
